head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Travel
Designer: Sookhee Lee
URL:      www.plyfly.net
----------------------------------------------- */

/* Variable definitions
   ====================
   <Variable name="keycolor" description="Main Color" type="color" default="#539bcd" value="#ffffff"/>

   <Group description="Page Text" selector="body">
     <Variable name="body.font" description="Font" type="font"
         default="normal normal 13px 'Trebuchet MS',Trebuchet,sans-serif" value="normal normal 14px &#39;Trebuchet MS&#39;, Trebuchet, Arial, sans-serif"/>
     <Variable name="body.text.color" description="Text Color" type="color" default="#bbbbbb" value="#444444"/>
   </Group>

   <Group description="Backgrounds" selector=".body-fauxcolumns-outer">
     <Variable name="body.background.color" description="Outer Background" type="color" default="#539bcd" value="#ffffff"/>
     <Variable name="content.background.color" description="Main Background" type="color" default="transparent" value="transparent"/>
   </Group>

   <Group description="Links" selector=".main-outer">
     <Variable name="link.color" description="Link Color" type="color" default="#ff9900" value="#1175a4"/>
     <Variable name="link.visited.color" description="Visited Color" type="color" default="#b87209" value="#dc6f93"/>
     <Variable name="link.hover.color" description="Hover Color" type="color" default="#ff9900" value="#dc6f93"/>
   </Group>

   <Group description="Blog Title" selector=".header h1">
     <Variable name="header.font" description="Font" type="font"
         default="normal normal 60px 'Trebuchet MS',Trebuchet,sans-serif" value="normal normal 0px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="header.text.color" description="Text Color" type="color" default="#ffffff"  value="rgba(0, 0, 0, 0)"/>
   </Group>

   <Group description="Blog Description" selector=".header .description">
     <Variable name="description.text.color" description="Description Color" type="color"
         default="$(body.text.color)"  value="#666666"/>
   </Group>

   <Group description="Tabs Text" selector=".tabs-inner .widget li a">
     <Variable name="tabs.font" description="Font" type="font"
         default="normal bold 16px 'Trebuchet MS',Trebuchet,sans-serif" value="normal bold 16px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="tabs.text.color" description="Text Color" type="color" default="#ffffff" value="#ffffff"/>
     <Variable name="tabs.selected.text.color" description="Selected Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Tabs Background" selector=".tabs-outer .PageList">
     <Variable name="tabs.background.color" description="Background Color" type="color" default="transparent" value="transparent"/>
     <Variable name="tabs.selected.background.color" description="Selected Color" type="color" default="transparent" value="transparent"/>
   </Group>

   <Group description="Date Header" selector=".main-inner h2.date-header">
     <Variable name="date.font" description="Font" type="font"
         default="normal normal 14px 'Trebuchet MS',Trebuchet,sans-serif" value="normal normal 14px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="date.text.color" description="Text Color" type="color" default="$(body.text.color)" value="#666666"/>
   </Group>

   <Group description="Post Title" selector="h3.post-title a">
     <Variable name="post.title.font" description="Font" type="font"
         default="normal bold 20px 'Trebuchet MS',Trebuchet,sans-serif" value="normal bold 20px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="post.title.text.color" description="Text Color" type="color"
         default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Post Background" selector=".column-center-inner">
     <Variable name="post.background.color" description="Background Color" type="color"
         default="transparent" value="transparent"/>
     <Variable name="post.background.url" description="Post Background URL" type="url" default="none" value="none"/>
   </Group>

   <Group description="Gadget Title Color" selector="h2">
     <Variable name="widget.title.font" description="Font" type="font"
        default="normal bold 14px 'Trebuchet MS',Trebuchet,sans-serif" value="normal bold 14px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="widget.title.text.color" description="Title Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Gadget Text" selector=".footer-inner .widget, .sidebar .widget">
     <Variable name="widget.font" description="Font" type="font"
        default="$(body.font)" value="normal normal 13px &#39;Trebuchet MS&#39;,Trebuchet,sans-serif"/>
     <Variable name="widget.text.color" description="Text Color" type="color" default="$(body.text.color)" value="#666666"/>
   </Group>

   <Group description="Gadget Links" selector=".sidebar .widget">
     <Variable name="widget.link.color" description="Link Color" type="color" default="$(body.text.color)" value="#666666"/>
     <Variable name="widget.link.visited.color" description="Visited Color" type="color" default="$(link.visited.color)" value="#436590"/>
     <Variable name="widget.alternate.text.color" description="Alternate Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Sidebar Background" selector=".column-left-inner .column-right-inner">
     <Variable name="widget.outer.background.color" description="Background Color" type="color" default="transparent"  value="transparent"/>
     <Variable name="widget.border.bevel.color" description="Bevel Color" type="color" default="transparent"  value="transparent"/>
   </Group>

   <Variable name="body.background" description="Body Background" type="background"
       color="$(body.background.color)" default="$(color) none repeat-x scroll top center" value="$(color) url(https://1.bp.blogspot.com/-WLeEYEMpgnI/WHUt-M8BWpI/AAAAAAAAFNw/yYQIzjml3Lg70TvfiEaKzVYjyr_hIsYZgCK4B/s1600/base_bg.png) no-repeat fixed top right"/>
   <Variable name="content.background" description="Content Background" type="background"
       color="$(content.background.color)" default="$(color) none repeat scroll top center" value="#ffffff url(//www.blogblog.com/1kt/travel/bg_container.png) repeat-x scroll top left"/>
   <Variable name="comments.background" description="Comments Background" type="background"
       default="#cccccc none repeat scroll top center" value="#cccccc none repeat scroll top center"/>

   <Variable name="content.imageBorder.top.space" description="Content Image Border Top Space" type="length" default="0" value="5px"/>
   <Variable name="content.imageBorder.top" description="Content Image Border Top" type="url" default="none" value="url(//www.blogblog.com/1kt/travel/bg_container.png)"/>

   <Variable name="content.margin" description="Content Margin Top" type="length" default="20px" value="20px"/>
   <Variable name="content.padding" description="Content Padding" type="length" default="20px" value="20px"/>
   <Variable name="content.posts.padding" description="Posts Content Padding" type="length" default="10px" value="10px"/>

   <Variable name="tabs.background.gradient" description="Tabs Background Gradient" type="url"
       default="url(//www.blogblog.com/1kt/travel/bg_black_50.png)" value="none"/>
   <Variable name="tabs.selected.background.gradient" description="Tabs Selected Background Gradient" type="url"
       default="url(//www.blogblog.com/1kt/travel/bg_black_50.png)" value="none"/>
   <Variable name="widget.outer.background.gradient" description="Sidebar Gradient" type="url"
       default="url(//www.blogblog.com/1kt/travel/bg_black_50.png)" value="none"/>
   <Variable name="footer.background.gradient" description="Footer Background Gradient" type="url" default="none" value="none"/>
   <Variable name="mobile.background.overlay" description="Mobile Background Overlay" type="string"
       default="transparent none repeat scroll top left" value="transparent none repeat scroll top left"/>
   <Variable name="mobile.button.color" description="Mobile Button Color" type="color" default="#ffffff"  value="#ffffff"/>
   <Variable name="startSide" description="Side where text starts in blog language" type="automatic" default="left"/>
   <Variable name="endSide" description="Side where text ends in blog language" type="automatic" default="right"/>
*/

/* =====================================================
   SAKURA PLANET - Design tokens (Rosa, Azul, Branco)
   Para trocar uma cor em todo o site, edite aqui.
   ===================================================== */
:root {
  --sp-rosa-100: #fff0f5;
  --sp-rosa-200: #ffd9e4;
  --sp-rosa-400: #faa7b9;  /* rosa da marca */
  --sp-rosa-600: #dc6f93;  /* hover / destaque */
  --sp-rosa-700: #b8446b;  /* texto rosa sobre branco, item ativo */
  --sp-azul-100: #e2f1f9;
  --sp-azul-300: #78a7c8;
  --sp-azul-500: #459dc7;  /* azul da marca */
  --sp-azul-700: #1175a4;  /* links, botoes */
  --sp-azul-900: #436590;  /* links no rodape */
  --sp-branco: #ffffff;
  --sp-texto: #444444;
  --sp-texto-suave: #666666;
  --sp-sombra: rgba(67, 101, 144, .18);
  --sp-fonte-titulo: 'Playball', cursive;
  --sp-fonte-menu: 'Sofia', cursive;
  --sp-fonte-destaque: 'Cookie', cursive;
  --sp-fonte-texto: 'Trebuchet MS', Trebuchet, Arial, sans-serif;
}

/* ---------- Base ---------- */
body {
  font: normal normal 14px/1.6 var(--sp-fonte-texto);
  color: var(--sp-texto);
  background: $(body.background);
}
html body .region-inner { min-width: 0; max-width: 100%; width: auto; }
a:link { color: var(--sp-azul-700); text-decoration: none; transition: color .3s ease-out; }
a:visited { color: var(--sp-rosa-600); text-decoration: none; }
a:hover { color: var(--sp-rosa-700); text-decoration: none; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--sp-azul-700); outline-offset: 2px; }
*::selection { background: var(--sp-rosa-200); color: var(--sp-texto); }
img { max-width: 100%; height: auto; }
.content-outer { margin: 0 auto; }
.content-outer .content-cap-top { background: transparent; }
.main-inner .date-outer { margin-bottom: 2em; }
.status-msg-wrap { display: none; }
.feed-links { display: none; }

/* ---------- Cabecalho ---------- */
.header-inner { margin-top: -50px; }
.Header .titlewrapper, .header-inner .Header .descriptionwrapper { padding-left: 10px; padding-right: 10px; }
.Header h1, .Header h1 a { font: normal normal 0px 'Trebuchet MS', Trebuchet, sans-serif; color: transparent; }
.Header .description { font-size: 130%; color: var(--sp-texto-suave); }

/* ---------- Menu horizontal ---------- */
.tabs-inner { margin: 1em 0 0; padding: 0; }
.tabs-inner .section { margin: 0; }
.tabs-inner .widget-content { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.menuattitude {
  background: var(--sp-rosa-400);
  border: 2px solid var(--sp-rosa-400);
  border-radius: 999px;
  font-family: var(--sp-fonte-menu);
  font-size: 16px;
  min-width: 100px;
  text-align: center;
  line-height: 26px;
  box-shadow: 0 2px 6px var(--sp-sombra);
  transition: background .3s, border-color .3s;
}
.menuattitude a { display: block; padding: 0 14px; color: var(--sp-texto); }
.menuattitude a:visited { color: var(--sp-texto); }
.menuattitude:hover { background: var(--sp-azul-700); border-color: var(--sp-azul-700); }
.menuattitude:hover a { color: var(--sp-branco); }

/* ---------- Titulos de widget (sidebar) ---------- */
.sidebar h2 {
  font-family: var(--sp-fonte-menu);
  font-size: 24px;
  font-weight: normal;
  color: var(--sp-texto);
  background: var(--sp-rosa-400);
  border-radius: 999px;
  padding: 4px 14px;
  margin: 0 0 .7em;
  text-align: center;
}

/* ---------- Layout principal ---------- */
.main-inner { padding: 20px 0; margin-top: -30px; }
.main-inner .column-center-inner { padding: 10px 0; }
.main-inner .column-center-inner .section { margin: 0 10px; }
.main-inner .column-right-inner { margin-left: 20px; }
.main-inner .fauxcolumn-right-outer .fauxcolumn-inner { margin-left: 20px; background: transparent; }
.main-inner .column-left-inner { margin-right: 20px; }
.main-inner .fauxcolumn-left-outer .fauxcolumn-inner { margin-right: 20px; background: transparent; }
.main-inner .column-left-inner, .main-inner .column-right-inner { padding: 15px 0; }

/* ---------- Posts ---------- */
.post-outer {
  background: var(--sp-branco);
  border-top: 4px solid var(--sp-rosa-400);
  border-radius: 8px;
  box-shadow: 0 4px 16px var(--sp-sombra);
  margin: 4px 2px 20px;
  padding: 20px 10px;
}
h3.post-title { margin: 20px 0 0; text-align: center; border-bottom: 1px solid var(--sp-azul-500); }
h3.post-title a {
  font-family: var(--sp-fonte-titulo);
  font-size: 30px;
  font-weight: normal;
  color: var(--sp-azul-700);
  text-shadow: 0 1px 1px #c5c5c5;
  transition: color .4s ease-in;
}
h3.post-title a:hover { color: var(--sp-rosa-700); text-decoration: none; }
.main-inner h2.date-header {
  font: normal normal 11px var(--sp-fonte-texto);
  color: var(--sp-branco);
  background: var(--sp-rosa-700);
  float: right;
  margin-right: -11px;
  padding: 4px 8px;
}
.post-header { margin: 0 0 1em; line-height: 1.6; }
.post-body { line-height: 1.5; position: relative; }
.post-body b, .post-body strong { color: var(--sp-azul-700); }
.post-body i, .post-body em { color: var(--sp-rosa-700); }
.post-body u { border-bottom: 1px dashed var(--sp-rosa-400); text-decoration: none; }
.post blockquote {
  background: var(--sp-azul-100);
  border-left: 6px solid var(--sp-azul-500);
  border-right: 6px solid var(--sp-azul-500);
  border-radius: 10px;
  font-size: 13px;
  text-align: center;
  padding: 8px 12px;
}
.post-footer {
  border-top: 1px dotted var(--sp-rosa-400);
  font-family: var(--sp-fonte-destaque);
  font-size: 20px;
  letter-spacing: 1px;
  margin: .73em 0;
  padding: 5px 8px;
}
.post-footer a { color: var(--sp-rosa-700); background: var(--sp-branco); }
.post-footer a:hover { color: var(--sp-branco); background: var(--sp-rosa-700); }
.comment-link { margin-left: 17px; color: var(--sp-texto-suave); background: var(--sp-branco); }
.jump-link img { margin-top: 6px; }
big { font-size: 50px; color: var(--sp-rosa-600); line-height: 30px; float: left; }

/* ---------- Sidebar ---------- */
.sidebar .widget {
  background: var(--sp-branco);
  border-bottom: 5px solid var(--sp-azul-500);
  border-radius: 8px;
  box-shadow: 0 3px 12px var(--sp-sombra);
  font: normal normal 12px var(--sp-fonte-texto);
  color: var(--sp-texto);
  margin: 10px 0 20px;
  padding: 10px;
}
.sidebar .widget:first-child { margin-top: 0; }
.sidebar .widget:last-child { margin-bottom: 0; }
.widget .zippy { color: var(--sp-texto); }
.menudecoração a { color: var(--sp-azul-700); }
.efeitoopc2 { width: 50px; height: 50px; opacity: .6; transition: .9s; text-align: center; }
.efeitoopc2:hover { opacity: 1; border-radius: 35px; }
#parceiros { opacity: .8; transition: all 1s ease; }
#parceiros:hover a { opacity: .2; }
#parceiros a { opacity: .8; transition: all 1s ease; }
#parceiros a:hover { opacity: 1; }

/* ---------- Paginacao numerada (pagina inicial, marcadores e busca) ---------- */
.pagenavi, #blog-pager { clear: both; text-align: center; margin: 30px auto 15px; padding: 8px 10px; font-size: 100%; }
.pagenavi a, .pagenavi span, #blog-pager a {
  display: inline-block;
  min-width: 38px;
  margin: 3px;
  padding: 6px 12px;
  box-sizing: border-box;
  font: bold 16px/1.4 var(--sp-fonte-texto);
  color: var(--sp-azul-700);
  background: var(--sp-branco);
  border: 2px solid var(--sp-rosa-400);
  border-radius: 999px;
  box-shadow: 0 2px 6px var(--sp-sombra);
  text-decoration: none;
  cursor: pointer;
  transition: background .3s ease-in-out, color .3s ease-in-out, border-color .3s ease-in-out;
}
.pagenavi a:visited, #blog-pager a:visited { color: var(--sp-azul-700); }
.pagenavi a:hover, #blog-pager a:hover { color: var(--sp-branco); background: var(--sp-azul-700); border-color: var(--sp-azul-700); }
.pagenavi .current { color: var(--sp-branco); background: var(--sp-rosa-700); border-color: var(--sp-rosa-700); cursor: default; }
.pagenavi .dots { min-width: 0; padding: 6px 2px; color: var(--sp-rosa-600); background: transparent; border: 0; box-shadow: none; cursor: default; }
.pagenavi .sp-loading { opacity: .6; pointer-events: none; }
#blog-pager-older-link, #blog-pager-newer-link { float: none; }

/* ---------- Comentarios ---------- */
#comments { background: var(--sp-branco); border-radius: 8px; padding: 15px; }
#comments h4, #comments .comment-author a, #comments .comment-timestamp a {
  color: var(--sp-azul-700);
  font-family: var(--sp-fonte-texto);
  font-size: 20px;
}
#comments .comment-author { padding-top: 1.5em; }
#comments .comment-author:first-child { padding-top: 0; border-top: none; }
.avatar-image-container { margin: .2em 0 0; }
.comments .comment-block { margin-left: 70px; }
.comment-header {
  background: var(--sp-rosa-700);
  border: 4px solid var(--sp-rosa-700);
  border-radius: 20px 20px 0 0;
  padding: 3px;
}
.comment-header a { color: var(--sp-branco) !important; font: bold 16px var(--sp-fonte-texto); }
.comment-header a:hover { color: var(--sp-rosa-200) !important; text-decoration: none; }
.comments .comments-content .datetime a { font-size: 10px !important; float: right; line-height: 16px; }
.comments .comments-content .comment-content {
  position: relative;
  margin-top: -10px;
  padding: 10px;
  background: var(--sp-branco);
  border: 1px dashed var(--sp-rosa-600);
  border-radius: 0 0 20px 20px;
  color: var(--sp-texto);
  font-size: 12px;
}
.comments .avatar-image-container {
  max-width: 50px; max-height: 50px; min-width: 50px; min-height: 50px;
  background: var(--sp-rosa-400);
  padding: 3px;
}
.comments .avatar-image-container img { max-width: 50px; max-height: 50px; min-width: 50px; min-height: 50px; }
.comments .comments-content .comment { padding: 20px 10px !important; margin-bottom: 15px !important; }
.comments .comment .comment-actions a {
  padding: 5px 8px;
  margin-right: 10px;
  background: var(--sp-azul-700);
  border: 1px solid var(--sp-azul-700);
  border-radius: 10px;
  color: var(--sp-branco) !important;
  font: bold 12px var(--sp-fonte-texto);
}
.comments .comment .comment-actions a:hover { background: var(--sp-rosa-700); border-color: var(--sp-rosa-700); text-decoration: none; }
.comments .continue { border-top: none; }
.comments .continue a { display: none; }
.comments .comments-content .icon.blog-author {
  background-repeat: no-repeat;
  background-image: url(data:image/png;base64,);
}

/* ---------- Rodape ---------- */
.footer-inner { background: transparent; }
.footer-inner .widget a:link, .footer-inner .widget a:visited { color: var(--sp-azul-900); }
.footer-inner .widget a:hover { color: var(--sp-rosa-700); text-decoration: underline; }
#rodape-creditos {
  background: var(--sp-rosa-200);
  border-top: 4px solid var(--sp-rosa-400);
  color: var(--sp-texto);
  font: normal bold 14px var(--sp-fonte-texto);
  padding: 8px;
  text-align: center;
}
#rodape-creditos a:link, #rodape-creditos a:visited { color: var(--sp-azul-900); }
#rodape-creditos a:hover { color: var(--sp-rosa-700); text-decoration: underline; }

/* ---------- Botao voltar ao topo ---------- */
#sp-top {
  position: fixed; right: 16px; bottom: 16px; z-index: 1000;
  width: 44px; height: 44px; border: 2px solid var(--sp-branco); border-radius: 50%;
  background: linear-gradient(135deg, var(--sp-rosa-600), var(--sp-azul-700));
  color: var(--sp-branco); font: bold 22px/1 var(--sp-fonte-texto);
  box-shadow: 0 3px 10px var(--sp-sombra); cursor: pointer;
}
#sp-top[hidden] { display: none; }
#sp-top:hover { filter: brightness(1.1); }

/* ---------- Mobile ---------- */
body.mobile { padding: 0 10px; background-size: 100% auto; }
body.mobile .AdSense { margin: 0 -10px; }
.mobile-post-outer a { color: var(--sp-azul-700); }
.mobile-link-button { background-color: var(--sp-azul-700); }
.mobile-link-button a:link, .mobile-link-button a:visited { color: var(--sp-branco); }
@media (max-width: 600px) {
  .pagenavi a, .pagenavi span { min-width: 34px; padding: 5px 9px; font-size: 15px; }
  .pagenavi .sp-hide-sm { display: none; }
  h3.post-title a { font-size: 24px; }
}

head.b:template-skin:





body {
  min-width: $(content.width);
}

.content-outer, .content-fauxcolumn-outer, .region-inner {
  min-width: $(content.width);
  max-width: $(content.width);
  _width: $(content.width);
}

.main-inner .columns {
  padding-left: $(main.column.left.width);
  padding-right: $(main.column.right.width);
}

.main-inner .fauxcolumn-center-outer {
  left: $(main.column.left.width);
  right: $(main.column.right.width);
  /* IE6 does not respect left and right together */
  _width: expression(this.parentNode.offsetWidth -
      parseInt("$(main.column.left.width)") -
      parseInt("$(main.column.right.width)") + 'px');
}

.main-inner .fauxcolumn-left-outer {
  width: $(main.column.left.width);
}

.main-inner .fauxcolumn-right-outer {
  width: $(main.column.right.width);
}

.main-inner .column-left-outer {
  width: $(main.column.left.width);
  right: 100%;
  margin-left: -$(main.column.left.width);
}

.main-inner .column-right-outer {
  width: $(main.column.right.width);
  margin-right: -$(main.column.right.width);
}

#layout {
  min-width: 0;
}

#layout .content-outer {
  min-width: 0;
  width: 800px;
}

#layout .region-inner {
  min-width: 0;
  width: auto;
}

b:includable.script:
//
(function () {
  var CFG = { perPage: 5, window: 5, prev: '\u2039', next: '\u203A', first: 'Primeira', last: '\u00DAltima' };
  var box = document.getElementById('sp-pagenavi');
  if (!box || !window.fetch) { return; }
  var loc = window.location;
  var qs = new URLSearchParams(loc.search);
  var label = loc.pathname.match(/^\/search\/label\/([^\/]+)/);
  var term = qs.get('q');
  var perPage = parseInt(qs.get('max-results'), 10) || CFG.perPage;
  var feedUrl = loc.origin + '/feeds/posts/summary' + (label ? '/-/' + label[1] : '');
  var baseUrl = loc.origin + loc.pathname;
  var hash = loc.hash.match(/PageNo=(\d+)/);
  var current = hash ? parseInt(hash[1], 10) : 1;

  function feed(extra) {
    var url = feedUrl + '?alt=json&' + extra + (term ? '&q=' + encodeURIComponent(term) : '');
    return fetch(url).then(function (r) { if (!r.ok) { throw new Error('feed'); } return r.json(); });
  }
  function go(n) {
    if (n === 1) { loc.href = baseUrl + (term ? '?q=' + encodeURIComponent(term) : '') + '#PageNo=1'; return; }
    box.classList.add('sp-loading');
    feed('start-index=' + ((n - 1) * perPage) + '&max-results=1').then(function (j) {
      var d = j.feed.entry[0].published.$t.replace(/\.\d+/, '');
      loc.href = baseUrl + '?updated-max=' + encodeURIComponent(d) + '&max-results=' + perPage +
        (term ? '&q=' + encodeURIComponent(term) : '') + '#PageNo=' + n;
    }).catch(function () { box.classList.remove('sp-loading'); });
  }
  function item(txt, n, cls, title) {
    var el = document.createElement(n ? 'a' : 'span');
    el.textContent = txt;
    if (cls) { el.className = cls; }
    if (title) { el.title = title; el.setAttribute('aria-label', title); }
    if (n) {
      el.href = '#PageNo=' + n;
      el.addEventListener('click', function (e) { e.preventDefault(); go(n); });
    }
    return el;
  }
  function render(pages) {
    var from = Math.max(1, current - Math.floor(CFG.window / 2));
    var to = Math.min(pages, from + CFG.window - 1);
    from = Math.max(1, to - CFG.window + 1);
    var nav = document.createElement('nav');
    nav.setAttribute('aria-label', 'Pagina\u00E7\u00E3o');
    if (current > 1) { nav.appendChild(item(CFG.prev, current - 1, '', 'P\u00E1gina anterior')); }
    if (from > 1) {
      nav.appendChild(item('1', 1, 'sp-hide-sm', CFG.first));
      if (from > 2) { nav.appendChild(item('\u2026', 0, 'dots')); }
    }
    for (var i = from; i <= to; i++) {
      var el = item(String(i), i === current ? 0 : i, i === current ? 'current' : '', 'P\u00E1gina ' + i);
      if (i === current) { el.setAttribute('aria-current', 'page'); }
      nav.appendChild(el);
    }
    if (to < pages) {
      if (to < pages - 1) { nav.appendChild(item('\u2026', 0, 'dots')); }
      nav.appendChild(item(String(pages), pages, 'sp-hide-sm', CFG.last));
    }
    if (current < pages) { nav.appendChild(item(CFG.next, current + 1, '', 'Pr\u00F3xima p\u00E1gina')); }
    box.innerHTML = '';
    box.appendChild(nav);
  }
  feed('max-results=0').then(function (j) {
    var total = parseInt(j.feed.openSearch$totalResults.$t, 10);
    var pages = Math.ceil(total / perPage);
    if (current > pages) { current = pages; }
    if (pages > 1) { render(pages); } else { box.innerHTML = ''; }
  }).catch(function () { /* mantem os links nativos Mais recentes / Mais antigas */ });
})();
